    /**
     * Tests getting all MROFacilitys.
     *
     * @return    Collection
     */
    public List<MROFacility> testGetAll() throws Throwable {
    LOGGER.info( "MROFacilityTest:testGetAll() - Retrieving Collection of MROFacilitys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all MROFacility : " );
    List<MROFacility> collection  = null;

    try {
        // call the static get method on the MROFacilityService
        collection = service.getAllMROFacility();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            MROFacility currEntity  = null;
            Iterator<MROFacility> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getMROFacilityId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

